<template>
  <b-container fluid
               class="my-5">
    <!--    bb prediction-->
    <div id="patient-id"/>
    <b-row :class="checkVisibility(1)"
           class="justify-content-center my-5 bg-light-gray">
      <b-col md="6">
        <b-card no-body
                class="overflow-hidden"
                style="min-height: 350px;">
          <b-row no-gutters
                 class="justify-content-center">
            <b-col md="6"
                   class="bg-light bg-opacity-75">
              <b-icon-person-fill style="width: 250px; min-height: 350px; color:#a3a3a3;"></b-icon-person-fill>
            </b-col>
            <b-col md="6">
              <b-card-body style="margin-right: 16px">
                <b-card-text>
                  <h3 class="my-3">{{ patient.name }}</h3>
                  <hr>
                  <p>
                    Age: {{ patient.age }}
                    <br>
                    Sex: {{ patient.sex }}
                  </p>
                  <hr>
                  <p class="mt-4">
                    Level of riks predicted
                  </p>
                  <p class="risk-alert"
                     :class="patient.description==='High Risk' ? 'risk-alert-high' : 'risk-alert-low'">
                    {{
                      explanation.explanation.CCS_code_to_meaning[explanation.explanation.bb_pred]
                    }}
                  </p>
                </b-card-text>
              </b-card-body>
            </b-col>
          </b-row>
        </b-card>
      </b-col>
    </b-row>
    <b-button @click="step++"
              class="mb-3 align-content-end btn-sm"
              variant="outline-secondary"
              href="#explanation">Get the explanation
    </b-button>
    <!--     bb explanation-->
    <div id="explanation"/>
    <b-row :class="checkVisibility(2)"
           class="justify-content-center my-5"
           >
      <b-col class="col-md-4">
        <h6>- EXPLANATION -</h6>
        <hr>
        <strong> {{ explanation.readable_explanation }}</strong>
        <hr>
        <b-button @click="step++"
                  class="my-1 align-content-end btn-sm"
                  variant="outline-secondary"
                  href="#diagnoses">Show diagnoses
        </b-button>
      </b-col>
    </b-row>
    <!--    diagnoses-->
    <div id="diagnoses"/>
    <b-row :class="checkVisibility(3)"
           class="justify-content-center my-5">
      <b-col class="col-md-4 mt-3">
        <h6>- DIAGNOSES -</h6>
        <hr>
        <p> Visualize the diagnoses considered relevant for the AI system prediction as a temporal sequence of events </p>
      </b-col>
      <div class="w-100"></div>
      <b-col class="mt-3">
        <div id="viz_step_three"></div>
        <div class="w-100"></div>
        <b-button @click="step++"
                  class="my-1 align-content-end btn-sm"
                  variant="outline-secondary"
                  href="#history">Show the complete clinical history
        </b-button>
      </b-col>
    </b-row>
    <!--    patient history-->
    <div id="history"/>
    <b-row :class="checkVisibility(4)" class="justify-content-center my-5">
      <b-col class="col-md-4 mt-3">
        <h6>- COMPLETE CLINICAL HISTORY -</h6>
        <hr>
        <p>Visualize the full clinical history of the patient and explore each clinical event with the mouseover. The ICD-9 codes are shown when you drag the mouse over the dots representing the diagnosis.</p>
      </b-col>
      <div class="w-100"></div>
      <b-col>
        <div id="viz_step_four"></div>
      </b-col>
    </b-row>
  </b-container>
</template>

<script>
import embed from 'vega-embed'

export default {
  name: "PatientView",
  props: {
    patient: Object,
  },
  data() {
    return {
      explanation: {
        explanation: {CCS_code_to_meaning: '', bb_pred: [0]},
        readable_explanation: ''
      },
      step: 0
    }
  },
  watch: {
    patient: function (newVal) {
      let baseUrl = process.env.BASE_URL || '/';
      if (!baseUrl.endsWith('/')) {
        baseUrl += '/';
      }
      const allFiles = [
        `${baseUrl}data/multi_explanation_at10_20_30_binary_${newVal.key}.json`,
        `${baseUrl}data/step3_multi_explanation_at10_20_30_binary_${newVal.key}.json`,
        `${baseUrl}data/step4_multi_explanation_at10_20_30_binary_${newVal.key}.json`
      ]
      Promise.all(allFiles.map(d => fetch(d).then(response => response.json()))).then(values => {
        console.log(values);
        this.explanation = values[0].explanation_binary;
        this.explanation.readable_explanation = this.explanation.readable_explanation
            .substring(0, this.explanation.readable_explanation.indexOf('THEREFORE'))
            .replace(/ *\([^)]*\) */g, " ")
        embed('#viz_step_three', values[1], {actions: false});
        embed('#viz_step_four', values[2], {actions: false});
        this.step = 2
      })

    }
  },
  methods: {
    checkVisibility(step) {
      return {visible: (this.step > step), invisible: !(this.step > step)}
    }

  }
}


</script>

